changeSet.sql:
ALTER TABLE credenciamento_empresarial ADD COLUMN excluido_em TIMESTAMPTZ;
ALTER TABLE credenciamento_empresarial DROP CONSTRAINT uk_credenciamento_solicitante_provedor;
CREATE UNIQUE INDEX uk_credenciamento_solicitante_provedor
    ON credenciamento_empresarial (id_solicitante, provedor) WHERE excluido_em IS NULL;

rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM credenciamento_empresarial WHERE excluido_em IS NOT NULL) THEN
        RAISE EXCEPTION 'Existem formulários excluídos. Preserve o histórico antes de reverter esta migração.';
    END IF;
END; $$;
DROP INDEX uk_credenciamento_solicitante_provedor;
ALTER TABLE credenciamento_empresarial
    ADD CONSTRAINT uk_credenciamento_solicitante_provedor UNIQUE (id_solicitante, provedor);
ALTER TABLE credenciamento_empresarial DROP COLUMN excluido_em;
